const XLSX = require('xlsx');
const filePath = '/workspace/testbed/data/travel_expenses.xlsx';
const wb = XLSX.readFile(filePath);
const ws = wb.Sheets[wb.SheetNames[0]];
const data = XLSX.utils.sheet_to_json(ws, {header:1});

// Find the row with C4C633
let targetRow = -1;
for (let i = 1; i < data.length; i++) {
  if (data[i][0] === 'C4C633') {
    targetRow = i;
    break;
  }
}

if (targetRow === -1) {
  console.log('Booking not found!');
  process.exit(1);
}

// Dates column is E (index 4), row in sheet is targetRow+1 (1-indexed)
const cellRef = 'E' + (targetRow + 1);
console.log('Updating cell:', cellRef, 'in row', targetRow + 1);

ws[cellRef] = { t: 's', v: '2026-10-01 to 2026-10-05' };
XLSX.writeFile(wb, filePath);
console.log('Done! Updated Dates for C4C633.');
"

